describe('Dropdown Selection on the Internet Heroku App', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
  });

  it('should select an option from the dropdown and apply the value', () => {
    // Verify initial state
    cy.get('[data-testid="dropdown-select"]').should('be.visible');
    cy.get('[data-testid="dropdown-select"]').should('have.value', '');
    cy.get('[data-testid="dropdown-select"]').should('contain', 'Please select an option');

    // Select the second option
    cy.get('[data-testid="dropdown-select"]').select('Option 2');

    // Verify selection was applied
    cy.get('[data-testid="dropdown-select"]').should('have.value', '2');
    cy.get('[data-testid="dropdown-select"]').should('contain', 'Option 2');
    cy.get('[data-testid="dropdown-select"]').should('not.contain', 'Please select an option');
  });

  it('should handle selecting the first option and verify its value', () => {
    // Verify initial state
    cy.get('[data-testid="dropdown-select"]').should('be.visible');
    cy.get('[data-testid="dropdown-select"]').should('have.value', '');

    // Select the first option
    cy.get('[data-testid="dropdown-select"]').select('Option 1');

    // Verify selection was applied
    cy.get('[data-testid="dropdown-select"]').should('have.value', '1');
    cy.get('[data-testid="dropdown-select"]').should('contain', 'Option 1');
    cy.get('[data-testid="dropdown-select"]').should('not.contain', 'Please select an option');
  });
});
